content.query:
// VM Heartbeat Status
Heartbeat
| where TimeGenerated {timeRange}
| summarize LastHeartbeat = max(TimeGenerated) by Computer, ResourceGroup, _ResourceId
| extend Status = iif(LastHeartbeat < ago(5m), 'Offline', 'Online')
| summarize Online = countif(Status == 'Online'), Offline = countif(Status == 'Offline')

// CPU Utilization by VM (avg, p95)
Perf
| where TimeGenerated {timeRange}
| where ObjectName == 'Processor' and CounterName == '% Processor Time' and InstanceName == '_Total'
| summarize AvgCPU = avg(CounterValue), P95CPU = percentile(CounterValue, 95) by Computer
| order by P95CPU desc

// CPU trend (aggregated hourly)
Perf
| where TimeGenerated {timeRange}
| where ObjectName == 'Processor' and CounterName == '% Processor Time' and InstanceName == '_Total'
| summarize AvgCPU = avg(CounterValue) by bin(TimeGenerated, 1h)
| order by TimeGenerated asc
